#include "dblyat/win32_kernel32_invoke.h"
#include <stdint.h>
#include <unistd.h>
#define CHECK(x) do { if (!(x)) return 0; } while (0)
static void fill(void *p,size_t n,uint8_t v){uint8_t*b=p;size_t i;for(i=0;i<n;++i)b[i]=v;}
static int same(const void*a,const void*b,size_t n){const uint8_t*x=a,*y=b;size_t i;for(i=0;i<n;++i)if(x[i]!=y[i])return 0;return 1;}
static void make_request(db_gateway_invoke_request *r,uint32_t symbol,uint32_t handler,size_t argc){fill(r,sizeof(*r),0u);r->rip=UINT64_C(0x10040);r->slot_address=r->rip;r->guest_rsp=UINT64_C(0x70000010);r->return_address=UINT64_C(0x401000);r->slot_index=1u;r->argument_count=argc;r->provider_id=DB_WIN32_PROVIDER_KERNEL32;r->symbol_id=symbol;r->handler_id=handler;}
static int preserved(db_gateway_invoke_request*r,db_win32_kernel32_state*s,db_win32_kernel32_invoke_status expected){db_win32_kernel32_state out,before_out;db_gateway_invoke_result result,before_result;fill(&out,sizeof(out),0xa5);fill(&result,sizeof(result),0x5a);before_out=out;before_result=result;CHECK(db_win32_kernel32_invoke_plan(r,s,&out,&result)==expected);CHECK(same(&out,&before_out,sizeof(out)));CHECK(same(&result,&before_result,sizeof(result)));return 1;}
static int success(void){db_gateway_invoke_request r;db_win32_kernel32_state s={123u,456u,77u,0u},out;db_gateway_invoke_result result;make_request(&r,DB_WIN32_SYMBOL_KERNEL32_GET_CURRENT_PROCESS_ID,DB_WIN32_HANDLER_KERNEL32_GET_CURRENT_PROCESS_ID,0u);CHECK(db_win32_kernel32_invoke_plan(&r,&s,&out,&result)==DB_WIN32_KERNEL32_INVOKE_OK);CHECK(out.process_id==123u&&out.thread_id==456u&&out.last_error==77u&&out.reserved==0u);CHECK(result.raw_result==123u&&result.rip==r.rip&&result.slot_address==r.slot_address&&result.slot_index==r.slot_index&&result.provider_id==r.provider_id&&result.symbol_id==r.symbol_id&&result.handler_id==r.handler_id&&result.reserved==0u);make_request(&r,DB_WIN32_SYMBOL_KERNEL32_SET_LAST_ERROR,DB_WIN32_HANDLER_KERNEL32_SET_LAST_ERROR,1u);r.arguments[0]=999u;CHECK(db_win32_kernel32_invoke_plan(&r,&s,&out,&result)==DB_WIN32_KERNEL32_INVOKE_OK);CHECK(out.last_error==999u&&s.last_error==77u&&result.raw_result==0u);return 1;}
static int failures(void){db_gateway_invoke_request r;db_win32_kernel32_state s={1u,2u,3u,0u};make_request(&r,DB_WIN32_SYMBOL_KERNEL32_GET_CURRENT_PROCESS_ID,DB_WIN32_HANDLER_KERNEL32_GET_CURRENT_PROCESS_ID,0u);r.provider_id=9u;CHECK(preserved(&r,&s,DB_WIN32_KERNEL32_INVOKE_BAD_REQUEST));make_request(&r,DB_WIN32_SYMBOL_KERNEL32_GET_CURRENT_THREAD_ID,DB_WIN32_HANDLER_KERNEL32_GET_CURRENT_PROCESS_ID,0u);CHECK(preserved(&r,&s,DB_WIN32_KERNEL32_INVOKE_BAD_REQUEST));make_request(&r,DB_WIN32_SYMBOL_KERNEL32_GET_LAST_ERROR,DB_WIN32_HANDLER_KERNEL32_GET_LAST_ERROR,0u);r.arguments[1]=1u;CHECK(preserved(&r,&s,DB_WIN32_KERNEL32_INVOKE_BAD_REQUEST));make_request(&r,DB_WIN32_SYMBOL_KERNEL32_SET_LAST_ERROR,DB_WIN32_HANDLER_KERNEL32_SET_LAST_ERROR,1u);r.arguments[0]=UINT64_C(0x100000000);CHECK(preserved(&r,&s,DB_WIN32_KERNEL32_INVOKE_PROVIDER_FAILED));s.process_id=0u;r.arguments[0]=1u;CHECK(preserved(&r,&s,DB_WIN32_KERNEL32_INVOKE_PROVIDER_FAILED));return 1;}
static int aliases(void){db_gateway_invoke_request r;db_win32_kernel32_state s={1u,2u,3u,0u},out;db_gateway_invoke_result result;union u { db_win32_kernel32_state state; db_gateway_invoke_result result; } a;make_request(&r,DB_WIN32_SYMBOL_KERNEL32_GET_CURRENT_PROCESS_ID,DB_WIN32_HANDLER_KERNEL32_GET_CURRENT_PROCESS_ID,0u);CHECK(db_win32_kernel32_invoke_plan(NULL,&s,&out,&result)==DB_WIN32_KERNEL32_INVOKE_NULL_ARGUMENT);CHECK(db_win32_kernel32_invoke_plan(&r,&s,&a.state,&a.result)==DB_WIN32_KERNEL32_INVOKE_BUFFER_OVERLAP);CHECK(db_win32_kernel32_invoke_plan(&r,&s,&s,&result)==DB_WIN32_KERNEL32_INVOKE_BUFFER_OVERLAP);return 1;}
int main(void){static const char ok[]="WIN32 KERNEL32 INVOKE TEST: PASS\n";static const char bad[]="WIN32 KERNEL32 INVOKE TEST: FAIL\n";if(success()&&failures()&&aliases()){(void)write(STDOUT_FILENO,ok,sizeof(ok)-1u);return 0;}(void)write(STDERR_FILENO,bad,sizeof(bad)-1u);return 1;}
